from pathlib import Path
root=Path(__file__).resolve().parent
parts=[]
def sprite(x,y,w,h,bounds,label):
 a,b,c,d=bounds;scale=w/(c-a)
 return f'<div class="sprite" style="left:{x}px;top:{y}px;width:{w}px;height:{h}px" aria-label="{label}"><img src="inventory-reference.jpg" alt="" style="width:{1536*scale}px;left:{-a*scale}px;top:{-b*scale}px"></div>'
# Exact source identity: IMG_2995 is Inventory. IMG_2994 is Character and is not used.
parts.append(sprite(590,135,285,570,(614,205,928,833),'Geralt from the owner Inventory reference'))
for x,y,bounds,label in [(420,155,(430,244,496,346),'Steel weapon'),(498,155,(519,244,581,346),'Silver sword'),(930,155,(940,252,997,345),'Chest armor'),(1002,155,(1009,252,1066,345),'Gloves'),(930,277,(940,384,997,472),'Trousers'),(1002,277,(1009,384,1066,472),'Boots')]:
 parts.append(sprite(x,y,53,87,bounds,label));parts.append(f'<span class="label" style="left:{x-10}px;top:{y+91}px;width:75px">{label}</span>')
for x,y,bounds,label in [(420,285,(439,400,498,480),'Bolts'),(498,285,(520,400,581,480),'Ranged weapon'),(420,423,(449,542,495,590),'Consumable'),(498,423,(545,535,590,586),'Consumable'),(420,498,(449,609,494,651),'Consumable'),(498,498,(547,605,587,649),'Consumable'),(420,599,(459,705,505,747),'Bomb'),(498,599,(547,701,595,748),'Pocket')]:parts.append(sprite(x,y,42,45,bounds,label))
css='''@page{size:1200px 850px;margin:0}*{box-sizing:border-box}body{margin:0;background:#070b12;color:#e3e0dc;font-family:"DejaVu Sans Condensed",sans-serif}.page{position:relative;width:1200px;height:850px;background:radial-gradient(ellipse at 55% 60%,#1a2035,#090d17 85%)}header{height:40px;padding:11px 22px;font-size:13px;border-bottom:1px solid #727784;color:#b9bdc7}.nav{position:absolute;left:30px;top:60px;width:1120px;height:60px;display:flex;justify-content:space-around;font-size:12px}.nav span{padding:15px 13px}.nav .selected{background:#b2ad9c;color:#1d1b1a}.sprite{position:absolute;overflow:hidden}.sprite img{position:absolute;max-width:none}.label{position:absolute;text-align:center;font-size:10px;color:#b6b6bf}.frame{position:absolute;border:1px solid #575b6b}.hint{position:absolute;font-size:11px;color:#c6c7d0}.bottom{position:absolute;left:0;bottom:0;width:1200px;height:55px;border-top:1px solid #747a85;padding:10px 22px;font-size:12px}button{font:12px "DejaVu Sans Condensed",sans-serif;background:#121722;color:#d7d8dd;border:1px solid #747a85;padding:6px 20px;margin-right:8px;display:inline-block;height:32px;line-height:16px}.note{position:absolute;left:28px;top:749px;font-size:11px;color:#a5a9b4}.inventory{position:absolute;left:25px;top:150px;width:340px;height:550px;border:1px solid #575b6b;padding:15px}.inventory img{width:100%;height:auto}.inventory p{font-size:11px;line-height:1.6;color:#b3b7c0}'''
html='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Inventory layout proof — IMG_2995</title><style>'+css+'</style></head><body><main class="page"><header>PHOENIX · Inventory reconstruction study</header><div class="nav"><span>GLOSSARY</span><span>ALCHEMY</span><span class="selected">INVENTORY</span><span>WORLD MAP</span><span>QUESTS</span><span>CHARACTER</span><span>MEDITATION</span></div><section class="inventory"><h3>ARMOR</h3>'+sprite(40,210,190,200,(0,300,215,530),'Visible inventory portion from supplied reference')+'</section><div class="frame" style="left:410px;top:145px;width:155px;height:240px"></div><div class="frame" style="left:410px;top:412px;width:155px;height:151px"></div><div class="frame" style="left:920px;top:145px;width:150px;height:245px"></div>'+''.join(parts)+'<span class="hint" style="left:934px;top:560px">VITALITY</span><span class="hint" style="left:1010px;top:560px">TOXICITY</span><p class="note">Reference: owner IMG_2995. Photo-derived art, perspective and camera cast remain provisional. Static HTML/CSS render; not a game screenshot.</p><footer class="bottom"><button>Save</button><button>Save a copy</button><span>Wolf navigation · Phoenix additions outside the game-area layout</span></footer></main></body></html>'
(root/'index.html').write_text(html)
